import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import LandingPage from './pages/LandingPage';
import TenantDashboard from './pages/TenantDashboard';
import LandlordDashboard from './pages/LandlordDashboard';
import PropertyDetails from './pages/PropertyDetails';
import DiscoverMap from './pages/DiscoverMap';
import MessagingPortal from './pages/MessagingPortal';
import CheckoutPage from './pages/CheckoutPage';
import LandlordAddListing from './pages/LandlordAddListing';
import LandlordDocuments from './pages/LandlordDocuments';
import HostEarnings from './pages/HostEarnings';
import HostBookings from './pages/HostBookings';

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<LandingPage />} />
        <Route path="/tenant" element={<TenantDashboard />} />
        <Route path="/landlord" element={<LandlordDashboard />} />
        <Route path="/details" element={<PropertyDetails />} />
        <Route path="/discover" element={<DiscoverMap />} />
        <Route path="/messages" element={<MessagingPortal />} />
        <Route path="/checkout" element={<CheckoutPage />} />
        <Route path="/landlord/add" element={<LandlordAddListing />} />
        <Route path="/landlord/documents" element={<LandlordDocuments />} />
        <Route path="/landlord/listings" element={<LandlordDashboard />} />
        <Route path="/landlord/earnings" element={<HostEarnings />} />
        <Route path="/landlord/bookings" element={<HostBookings />} />
        <Route path="/discovery" element={<DiscoverMap />} />
        <Route path="/property-details" element={<PropertyDetails />} />
      </Routes>
    </Router>
  );
}

export default App;
